Chapter: Nine days

The paragraph: In June the share price fell from 104.5 euros to 1.28 euros. Nobody could stop it.

This graphic covers: The share price fell from 104.5 euros to 1.28 euros.
Length: 6.0 s

Words spoken in it, from its start:
0.3 s  Nobody
0.8 s  asked.
1.4 s  Nobody
1.9 s  checked.
2.5 s  Nobody
3.0 s  knew.

Intent: Nobody asked, nobody checked, nobody knew.
Rests on claims: 4

A passing design of this technique (kinetic-word-stack: a repeated word built once and kept, what changes after it rolling past on a 3D drum, the last in the accent), in this sandbox and on the tokens, for its mechanics, its timing and its standard. It uses: persistent actor, drum, density from hierarchy. Its concept came from its own narration: find this slot's own rather than reusing its layout. Its words and figures are its own; yours come from this slot and its claims:
````jsx
// Concept: one "Nobody", three verdicts. The narration says the same word three times, so
// the word is built once and stays; what changes is the verdict beside it, rolling past on
// a drum like a reel stopping, each one pushed up and back by the next. The concept comes
// from this line's repetition: a line with a different shape needs its own concept.
// Storyboard, on the narration's clock:
//   0.0 s  the hook: the empty three-part underline where "Nobody" will stand
//   0.3 s  "Nobody" rises out of its underline, the first part filling
//   0.85 s "asked." rolls up from under the line into place
//   1.4 s  "Nobody" again: the second part of its underline snaps full
//   1.95 s "checked." rolls in and pushes "asked." up and back around the drum
//   2.5 s  the third part
//   3.05 s "knew." rolls in on the hero spring in the accent, the reel clicking to a stop,
//          the earlier verdicts tilted back and dimmed above it
//   to the end: the stack holds while the camera keeps a slow push
// In portrait the anchor stacks above the drum and the drum turns the other way, so the
// earlier verdicts fall away below rather than into the anchor.
// Nothing fades out and nothing is replaced: every verdict stays on the drum.
const STEP = 0.45 // the angle between two verdicts on the drum, in radians (about 26 degrees)

// Helpers, called directly: 0 to 1 over lengthMs from atMs, held at 1, one per curve,
// since each interpolate names its curve in the call.
function range(fps, atMs, lengthMs) {
  return [motion.frames(atMs, fps), motion.frames(atMs + lengthMs, fps)]
}
function arrive(frame, fps, atMs, lengthMs) {
  return Remotion.interpolate(frame, range(fps, atMs, lengthMs), [0, 1], {
    easing: motion.ease.enter, extrapolateLeft: 'clamp', extrapolateRight: 'clamp',
  })
}
function travel(frame, fps, atMs, lengthMs) {
  return Remotion.interpolate(frame, range(fps, atMs, lengthMs), [0, 1], {
    easing: motion.ease.move, extrapolateLeft: 'clamp', extrapolateRight: 'clamp',
  })
}

// Motion blur that follows speed: a move of more than a few pixels a frame softens, and
// only while it is moving. moved is how far the element travelled since the last frame.
function blurFor(moved, unit) {
  const px = Math.min(8, Math.abs(moved) / (6 * unit)) * unit
  return px > 0.4 * unit ? 'blur(' + px.toFixed(2) + 'px)' : 'none'
}

// The narration as sentences: a word that ends a sentence closes it.
function sentencesOf(words) {
  const sentences = [[]]
  words.forEach((word) => {
    sentences[sentences.length - 1].push(word)
    if (/[.!?]$/.test(word.text)) sentences.push([])
  })
  return sentences.filter((sentence) => sentence.length > 0)
}

// Where the drum stands at a frame, in verdicts: -1 before the first, n - 1 once all have
// rolled in. Each verdict rolls in as its first word is said; the last one on the hero spring.
function drumAt(frame, fps, verdicts) {
  const last = verdicts.length - 1
  return verdicts.reduce((at, verdict, index) => {
    const start = verdict[0].atMs
    const roll = index === last
      ? Remotion.spring({ frame, fps, delay: motion.frames(start, fps), config: motion.spring.hero })
      : arrive(frame, fps, start, motion.ms.enter)
    return at + roll
  }, -1)
}

// A helper, called directly: one verdict on the drum. rel is how far round the drum it sits
// from the reading line, in radians: 0 faces the camera, more is further up and back.
function verdictOn(words, index, spec) {
  const { radius, unit, colors } = spec
  const rel = spec.turn * (spec.drum - index) * STEP
  const shown = Math.max(0, Math.min(1, 1 + spec.drum - index))
  const behind = Math.max(0, spec.drum - index)
  const hero = index === spec.last
  return (
    <div
      key={index}
      style={{
        position: 'absolute', left: 0, top: 0, whiteSpace: 'nowrap',
        color: hero ? colors.accent : colors.textPrimary,
        opacity: shown * Math.max(0.3, 1 - 0.32 * behind),
        // On a cylinder whose axis sits radius behind the reading line: up (or down) and back.
        transform: 'translateZ(' + -radius + 'px) rotateX(' + (rel * 180) / Math.PI
          + 'deg) translateZ(' + radius + 'px)',
        filter: spec.blur,
      }}
    >
      {words.map((word) => word.text).join(' ')}
    </div>
  )
}

// A helper, called directly: one part of the anchor's underline, filling as the word is said
// again, so the line under "Nobody" counts how many times it was said.
function tallyMark(word, index, frame, fps, unit, colors) {
  const snap = Remotion.spring({ frame, fps, delay: motion.frames(word.atMs, fps), config: motion.spring.snap })
  return (
    <div key={index} style={{ flex: 1, height: 8 * unit, backgroundColor: Remotion.withAlpha(colors.textSecondary, 0.25) }}>
      <div
        style={{
          width: '100%', height: '100%', backgroundColor: colors.accent,
          transform: 'scaleX(' + snap + ')', transformOrigin: 'left',
        }}
      />
    </div>
  )
}

function Graphic(props) {
  const frame = Remotion.useCurrentFrame()
  const { width, height, fps } = Remotion.useVideoConfig()
  const { colors, fonts } = props.brand
  const inset = props.safeArea
  const portrait = height > width
  const unit = Math.min(width, height) / 1080

  const sentences = React.useMemo(() => sentencesOf(props.words), [props.words])
  // The anchor is the word every sentence opens with; the rest of each sentence is its verdict.
  const anchor = sentences[0][0]
  const verdicts = sentences.map((sentence) => sentence.slice(1)).filter((verdict) => verdict.length > 0)
  const openers = sentences.map((sentence) => sentence[0])
  const last = verdicts.length - 1

  const drum = drumAt(frame, fps, verdicts)
  const drumBefore = drumAt(frame - 1, fps, verdicts)

  // Sized so the anchor and the longest verdict fit, side by side in landscape and stacked in
  // portrait (about 0.58 em a character).
  const room = width - inset.left - inset.right
  const longest = Math.max(...verdicts.map((verdict) => verdict.map((word) => word.text).join(' ').length))
  const fit = portrait ? Math.max(anchor.text.length, longest) : anchor.text.length + 1 + longest
  const size = Math.min((portrait ? 190 : 170) * unit, (0.9 * room) / (fit * 0.58))
  const turn = portrait ? -1 : 1
  // Far enough round the drum that one step apart is one line apart.
  const radius = (size * 0.95) / STEP
  const anchorIn = arrive(frame, fps, anchor.atMs, motion.ms.enter)
  const push = travel(frame, fps, 0, props.durationMs)

  return (
    <Remotion.AbsoluteFill
      style={{
        paddingTop: inset.top, paddingRight: inset.right,
        paddingBottom: inset.bottom, paddingLeft: inset.left,
        justifyContent: 'center', alignItems: 'center',
        transform: 'scale(' + (1 + 0.04 * push) + ')',
      }}
    >
      <div
        style={{
          display: 'flex', flexDirection: portrait ? 'column' : 'row', alignItems: 'flex-start',
          gap: (portrait ? 0.3 : 0.32) * size, fontFamily: fonts.heading, fontSize: size, lineHeight: 1,
          // Room for the verdicts the drum has turned away: above in landscape, below in portrait.
          paddingTop: portrait ? 0 : 1.5 * size, paddingBottom: portrait ? 1.5 * size : 0,
        }}
      >
        <div>
          <div style={{ clipPath: 'inset(-20% -5% 0 -5%)' }}>
            <div style={{ color: colors.textPrimary, transform: 'translateY(' + (1 - anchorIn) * size + 'px)' }}>
              {anchor.text}
            </div>
          </div>
          <div style={{ display: 'flex', gap: 10 * unit, marginTop: 0.14 * size, width: anchor.text.length * 0.58 * size }}>
            {openers.map((word, index) => tallyMark(word, index, frame, fps, unit, colors))}
          </div>
        </div>
        <div
          style={{
            position: 'relative', height: size, width: longest * 0.58 * size,
            perspective: 6 * size, perspectiveOrigin: '0 50%',
            // A reel window: a verdict comes out from behind the reading edge, never across the anchor.
            clipPath: portrait ? 'inset(0 -50% -400% -50%)' : 'inset(-400% -50% 0 -50%)',
          }}
        >
          {verdicts.map((words, index) =>
            verdictOn(words, index, {
              drum, last, radius, unit, colors, turn,
              blur: blurFor((drum - drumBefore) * STEP * radius, unit),
            }),
          )}
        </div>
      </div>
    </Remotion.AbsoluteFill>
  )
}

````
